"""Offline supplementary review UI. User data enters textContent, never HTML."""

PAGE = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>六风格审阅</title>
<style>body{margin:0;background:#f3f1eb;color:#233236;font:16px/1.7 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px}article,section{background:white;border:1px solid #d5d7d0;border-radius:12px;padding:24px;margin:20px 0}img{max-width:100%;height:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f4ef;padding:16px}label{display:block;margin:12px 0}input,select,textarea,button{font:inherit;padding:8px}textarea{width:95%;min-height:60px}button{border:0;border-radius:6px;background:#21424a;color:white;cursor:pointer}.views{display:flex;gap:20px;flex-wrap:wrap}.views figure{margin:0;width:360px;max-width:100%}.pair{border-bottom:1px solid #ddd;padding:16px 0}.dimension{display:inline-block;margin-right:16px}blockquote{font-size:24px;white-space:pre-wrap;border-left:4px solid #9b6849;padding-left:18px}.small{font-size:14px;color:#536068}.error{color:#9a372a}</style>
<main><h1>同一句 · 六种风格</h1><p>逐图检查，再比较15对风格。全部默认待审；保存本人判断后仍须回到项目导入。本页不批准人物归属、主卡或整组发布。</p>
<p>当前样张可能含“待审核”标签；样张效果获认可也不代表正式成品已批准。方形图只模拟裁切，会丢署名或截头，本次仅完整3:4交付。</p>
<section id="context"><h2>原句与上下文</h2></section><section id="reference"><h2>人物基准</h2></section>
<div id="styles"></div><section><h2>15对风格差异</h2><p>每对至少在三维存在实质差异，才可选通过。不能只凭颜色或配置不同判断。</p><div id="pairs"></div></section>
<section><h2>保存本人审阅</h2><label>审阅人 <input id="reviewer" type="text"></label><label><input id="attest" type="checkbox">我本人查看了图像和上下文，以上是我的判断</label><button id="save">下载六风格审阅记录</button><p id="message" role="status"></p><p class="small">未检查项继续待审。数据只在本页和下载文件中处理，不联网；文件可能含私有引文及上下文，请留在本机。</p></section></main>
<script>const data=__STYLE_DATA__;
const record=data.record, material=record.target.material;
const el=(tag,text,parent)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.append(n);return n;};
const select=(parent,onchange)=>{const s=el('select',undefined,parent);for(const [v,t] of [['pending','未检查'],['approved','通过'],['rejected','不通过']]){const o=el('option',t,s);o.value=v;}s.addEventListener('change',()=>onchange(s.value));return s;};
const image=(parent,url,alt)=>{const im=el('img',undefined,parent);im.src=url;im.alt=alt;return im;};
const context=document.getElementById('context');el('h3',material.book_title+' · '+material.character.name,context);el('blockquote',material.quote.display_text,context);
el('p','请区分原文场景还原与主题化延伸。画面和语句情绪相合，不等于小说中的时间、地点、动作已被逐细节还原。',context);
for(const passage of material.source_context.passages){el('h3',passage.chapter,context);el('pre',passage.text,context);}
if(material.source_context.omitted_ranges.length)el('p','以上为有明确间隔的原文片段，未展示部分不代表连续引文。',context);
if(material.approval_issues.length){const p=el('p','任务或来源尚有待处理项，导入时不能授予通过。',context);p.className='error';}
el('p','人物资料：'+JSON.stringify(material.character.traits||[]),document.getElementById('reference'));
image(document.getElementById('reference'),data.reference,'人物基准图');
const styleInputs=[];
for(const row of record.styles){const sid=row.style_id,a=el('article',undefined,document.getElementById('styles'));el('h2',data.labels[sid],a);const details=el('details',undefined,a);el('summary','查看完整原尺寸图',details);image(details,data.images[sid].full,'完整海报');const views=el('div',undefined,a);views.className='views';for(const [key,label] of [['mobile','360×480手机图'],['center_square_simulation','方形裁切模拟（非交付画幅）']]){const f=el('figure',undefined,views);image(f,data.images[sid][key],label);el('figcaption',label,f);}for(const [key,label] of Object.entries(data.checks)){const l=el('label',label+' ',a),s=select(l,v=>row.checks[key]=({pending:'pending',approved:'passed',rejected:'failed'})[v]);s.dataset.check=key;s.dataset.style=sid;}const l=el('label','本套结论 ',a);select(l,v=>row.status=v);const note=el('textarea',undefined,a);note.placeholder='修改意见或主题化配图说明';note.addEventListener('input',()=>row.note=note.value);el('p','图像SHA-256：'+material.styles.find(x=>x.style_id===sid).poster_sha256,a).className='small';styleInputs.push(row);}
for(const row of record.pairs){const p=el('div',undefined,document.getElementById('pairs'));p.className='pair';el('b',row.styles.map(x=>data.labels[x]).join(' / '),p);for(const [key,label] of Object.entries(data.dimensions)){const l=el('label',undefined,p);l.className='dimension';const c=el('input',undefined,l);c.type='checkbox';c.addEventListener('change',()=>{row.human_dimensions=[...p.querySelectorAll('input:checked')].map(x=>x.value);});c.value=key;l.append(document.createTextNode(label));}select(el('label','结论 ',p),v=>row.human_status=v);const note=el('textarea',undefined,p);note.placeholder='差异或修改说明';note.addEventListener('input',()=>row.note=note.value);}
document.getElementById('save').onclick=()=>{const message=document.getElementById('message'),who=document.getElementById('reviewer').value.trim();if(!who||!document.getElementById('attest').checked){message.textContent='请填写审阅人，并确认本人检查。';return;}for(const row of styleInputs){if(row.status==='approved'&&Object.values(row.checks).some(v=>v!=='passed')){message.textContent='请补齐通过样张的全部检查，或把结论保留为未检查。';return;}}for(const row of record.pairs){if(row.human_status==='approved'&&row.human_dimensions.length<3){message.textContent='通过的风格对须由本人勾选至少三维差异。';return;}}record.reviewer=who;record.attested=true;record.reviewed_at=new Date().toISOString();const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}));const a=el('a',undefined,document.body);a.href=url;a.download='six-style-human-review.json';a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);message.textContent='已保存本人记录；未检查项保持待审，请回到项目导入。';};
</script></html>'''
